{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-stat-rows.json
    Two figures of FeatureSplit as cards, then three features as checked rows.
    Props (p): features, stats. *}
{var $v_features = ($p['features'] ?? null)}
{var $v_stats = ($p['stats'] ?? null)}
{capture $c_11}
  {capture $c_4}
    {foreach ui_l($v_stats) as $v_s}
      {var $v_i = $iterator->counter0}
      {if ui_t(ui_lt($v_i, 2))}
        {capture $c_3}
          {capture $c_1}
            {=ui_text(ui_get($v_s, ['value']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => '2xl', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
          {capture $c_2}
            {=ui_text(ui_get($v_s, ['label']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0', 'Class' => 'rounded bg-card inset-ring inset-ring-border p-4', 'Attrs' => ui_attrs(['data-testid', 'feature-stat'])], 'children' => $c_3])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-2 gap-4'], 'children' => $c_4])|noescape}
  {capture $c_10}
    {foreach ui_l($v_features) as $v_f}
      {var $v_i = $iterator->counter0}
      {if ui_t(ui_lt($v_i, 3))}
        {capture $c_9}
          {capture $c_5}
            {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'check', 'Size' => 16]])|noescape}
          {/capture}
          {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'flex size-6 shrink-0 items-center justify-center rounded bg-primary text-primary-foreground'], 'children' => $c_5])|noescape}
          {capture $c_8}
            {capture $c_6}
              {=ui_text(ui_get($v_f, ['title']))}
            {/capture}
            {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_6])|noescape}
            {capture $c_7}
              {=ui_text(ui_get($v_f, ['text']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_7])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => 'min-w-0'], 'children' => $c_8])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'start', 'Attrs' => ui_attrs(['data-testid', 'feature-item'])], 'children' => $c_9])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch'], 'children' => $c_10])|noescape}
{/capture}
{=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '6', 'Align' => 'stretch'], 'children' => $c_11])|noescape}
